function A_inv = matrix_inverse_newt(A)
    tol = 1e-9;
    max_iter = 100;
    n = size(A, 1);
    I = eye(n);
    Xk = A' / (norm(A, 1) * norm(A, inf));

    for k = 1:max_iter
        Rk = I - A * Xk;
        Xk_new = Xk + Xk * Rk;

        % Stopping criterion based on the norm of the residual matrix
        if norm(Rk) < tol
            break;
        end

        Xk = Xk_new;
    end

    A_inv = Xk;
end

